using System;
using System.Collections.Generic;
using Godot;
using MiniRPG.Core.Data;
using MiniRPG.Core.World;

namespace MiniRPG.Module.Render;

/// <summary>
/// Isometric voxel renderer: renders multi-layer block world in 2.5D isometric view.
/// Each visible block draws top face (diamond) + left side + right side.
/// Side faces are programmatically generated by sampling the bottom edges of the top tile.
/// </summary>
public class IsometricVoxelRenderer
{
	private const int DefaultViewDepthAbove = 4;
	private const int DefaultViewDepthBelow = 2;
	private const int DefaultCharacterSheetFrameWidth = 128;
	private const int DefaultCharacterSheetFrameHeight = 128;
	private const float LeftDarken = 0.65f;
	private const float RightDarken = 0.80f;
	private static readonly float IsoSkewAngle = Mathf.Atan(0.5f);

	private readonly GameState _state;
	private readonly FogOfWarTracker _fogTracker;
	private readonly int _viewW;
	private readonly int _viewH;

	private Node2D? _root;
	private Camera2D? _camera;
	private TileMapRenderModule? _parentModule;

	private readonly List<Sprite2D> _spritePool = [];
	private int _spriteCount;
	private readonly List<VoxelDrawCommand> _drawCommands = [];
	private readonly List<EntityDrawCommand> _entityCommands = [];
	private int _lastDrawCommandCount;

	private readonly Dictionary<string, CachedBlockTextures> _textureCache = new();

	private static readonly Dictionary<string, Color> TerrainColors = new()
	{
		[Terrains.GrassBlock] = new Color(0.3f, 0.7f, 0.2f),
		[Terrains.Grass] = new Color(0.3f, 0.7f, 0.2f),
		[Terrains.Dirt] = new Color(0.55f, 0.35f, 0.15f),
		[Terrains.Stone] = new Color(0.5f, 0.5f, 0.5f),
		[Terrains.Sand] = new Color(0.9f, 0.85f, 0.6f),
		[Terrains.Water] = new Color(0.2f, 0.4f, 0.8f, 0.7f),
		[Terrains.Mountain] = new Color(0.4f, 0.4f, 0.45f),
		[Terrains.WallStone] = new Color(0.45f, 0.45f, 0.45f),
		[Terrains.WallSoil] = new Color(0.5f, 0.3f, 0.15f),
		[Terrains.WallGranite] = new Color(0.6f, 0.55f, 0.5f),
		[Terrains.WallObsidian] = new Color(0.15f, 0.1f, 0.2f),
		[Terrains.Tree] = new Color(0.15f, 0.5f, 0.1f),
		[Terrains.Snow] = new Color(0.95f, 0.95f, 1.0f),
		[Terrains.Ice] = new Color(0.7f, 0.85f, 1.0f, 0.8f),
		[Terrains.Lava] = new Color(1.0f, 0.3f, 0.0f),
		[Terrains.Floor] = new Color(0.6f, 0.55f, 0.45f),
		[Terrains.Rubble] = new Color(0.5f, 0.45f, 0.35f),
	};

	private static readonly Dictionary<string, string> CharacterSheetMap = new(StringComparer.OrdinalIgnoreCase)
	{
		["Idle"] = "Idle",
		["Walk"] = "Walk",
		["Run"] = "Run",
		["Attack_1"] = "Attack1",
		["Attack1"] = "Attack1",
		["Pain"] = "TakeDamage",
		["TakeDamage"] = "TakeDamage",
		["Die"] = "Die",
		["Special_1"] = "Special1",
		["Special1"] = "Special1",
	};

	public IsometricVoxelRenderer(GameState state, FogOfWarTracker fogTracker, int viewW, int viewH)
	{
		_state = state;
		_fogTracker = fogTracker;
		_viewW = viewW;
		_viewH = viewH;
	}

	public int LastSpriteCount => _spriteCount;
	public int LastDrawCommandCount => _lastDrawCommandCount;

	public void Init(Node2D root, TileSet tileSet, Camera2D? camera, TileMapRenderModule parentModule)
	{
		_root = root;
		_camera = camera;
		_parentModule = parentModule;
		_textureCache.Clear();
	}

	// ── Main Render Pass ──

	public void Render()
	{
		if (_state.World == null || _root == null) return;

		BeginFrame();

		var cx = _state.PlayerX;
		var cy = _state.PlayerY;
		var cz = _state.PlayerZ;
		var halfW = _viewW / 2;
		var halfH = _viewH / 2;
		var zMin = cz - DefaultViewDepthAbove;
		var zMax = cz + DefaultViewDepthBelow;

		_drawCommands.Clear();

		for (var wy = cy - halfH; wy <= cy + halfH; wy++)
		for (var wx = cx - halfW; wx <= cx + halfW; wx++)
		for (var wz = zMax; wz >= zMin; wz--)
		{
			var terrain = _state.World.GetTerrain(wx, wy, wz);
			if (terrain.StringId == Terrains.Air || terrain.StringId == Terrains.Void)
				continue;
			if (IsFullyOccluded(wx, wy, wz))
				continue;

			var drawTop = !_state.World.GetTerrain(wx, wy, wz - 1).IsOpaque;
			var drawLeft = !_state.World.GetTerrain(wx, wy + 1, wz).IsOpaque;
			var drawRight = !_state.World.GetTerrain(wx + 1, wy, wz).IsOpaque;

			if (!drawTop && !drawLeft && !drawRight)
				continue;

			_drawCommands.Add(new VoxelDrawCommand
			{
				WorldX = wx, WorldY = wy, WorldZ = wz,
				ScreenPos = IsoCoordUtil.WorldToScreen(wx, wy, wz),
				SortKey = IsoCoordUtil.SortKey(wx, wy, wz),
				Terrain = terrain,
				DrawTop = drawTop, DrawLeftSide = drawLeft, DrawRightSide = drawRight,
			});
		}

		_drawCommands.Sort(static (a, b) => a.SortKey.CompareTo(b.SortKey));
		CollectEntityCommands(cx, cy, cz, halfW, halfH, zMin, zMax);
		_lastDrawCommandCount = _drawCommands.Count + _entityCommands.Count;
		RenderScene();
		EndFrame();
		UpdateCamera(cx, cy, cz);
	}

	private bool IsFullyOccluded(int wx, int wy, int wz)
	{
		var w = _state.World!;
		return w.GetTerrain(wx, wy, wz - 1).IsOpaque
			&& w.GetTerrain(wx, wy + 1, wz).IsOpaque
			&& w.GetTerrain(wx + 1, wy, wz).IsOpaque;
	}

	// ── Drawing Methods ──

	private void DrawBlockTop(VoxelDrawCommand cmd)
	{
		var textures = GetOrCreateTextures(cmd.Terrain);
		if (textures.Top == null) return;
		var s = AcquireSprite();
		s.Centered = true;
		s.RegionEnabled = false;
		s.Scale = Vector2.One;
		s.Texture = textures.Top;
		s.Position = cmd.ScreenPos;
		s.Skew = 0f;
		s.ZIndex = 0;
		s.Modulate = GetVisionTint(cmd.WorldX, cmd.WorldY, cmd.WorldZ);
		s.Visible = true;
	}

	private void DrawLeftSide(VoxelDrawCommand cmd)
	{
		var textures = GetOrCreateTextures(cmd.Terrain);
		if (textures.Left == null) return;
		var s = AcquireSprite();
		s.Centered = true;
		s.RegionEnabled = false;
		s.Scale = Vector2.One;
		s.Texture = textures.Left;
		// Left side hangs from the left-bottom edge of the diamond
		s.Position = cmd.ScreenPos + new Vector2(-IsoCoordUtil.TileHalfW / 2f, IsoCoordUtil.TileHalfH + IsoCoordUtil.ZStep / 2f);
		s.Skew = IsoSkewAngle;
		s.ZIndex = 0;
		s.Modulate = GetVisionTint(cmd.WorldX, cmd.WorldY, cmd.WorldZ);
		s.Visible = true;
	}

	private void DrawRightSide(VoxelDrawCommand cmd)
	{
		var textures = GetOrCreateTextures(cmd.Terrain);
		if (textures.Right == null) return;
		var s = AcquireSprite();
		s.Centered = true;
		s.RegionEnabled = false;
		s.Scale = Vector2.One;
		s.Texture = textures.Right;
		// Right side hangs from the right-bottom edge of the diamond
		s.Position = cmd.ScreenPos + new Vector2(IsoCoordUtil.TileHalfW / 2f, IsoCoordUtil.TileHalfH + IsoCoordUtil.ZStep / 2f);
		s.Skew = -IsoSkewAngle;
		s.ZIndex = 0;
		s.Modulate = GetVisionTint(cmd.WorldX, cmd.WorldY, cmd.WorldZ);
		s.Visible = true;
	}

	private Color GetVisionTint(int wx, int wy, int wz)
	{
		var band = _fogTracker.GetVisionBand(wx, wy, wz);
		return band switch
		{
			PlayerVisionBand.Focused => Colors.White,
			PlayerVisionBand.Peripheral => new Color(0.50f, 0.50f, 0.56f),
			PlayerVisionBand.Memory => new Color(0.22f, 0.22f, 0.28f),
			_ => new Color(0f, 0f, 0f, 0f),
		};
	}

	// ── Texture Generation ──

	private CachedBlockTextures GetOrCreateTextures(TerrainDef terrain)
	{
		if (_textureCache.TryGetValue(terrain.StringId, out var cached))
			return cached;

		// Try to extract real tile from TileSet atlas via parent module
		Image? topImage = null;
		Texture2D? topTexture = null;

		if (_parentModule != null)
		{
			var atlasTexture = _parentModule.BuildTerrainTexture(terrain.StringId);
			if (atlasTexture != null)
			{
				topTexture = atlasTexture;
				topImage = ExtractImage(atlasTexture);
			}
		}

		// Fallback: generate solid-color diamond
		if (topImage == null)
		{
			var color = TerrainColors.GetValueOrDefault(terrain.StringId, new Color(0.5f, 0.5f, 0.5f));
			topImage = CreateDiamondImage(128, 64, color);
			topTexture = ImageTexture.CreateFromImage(topImage);
		}

		// Generate side faces by sampling bottom edges of the top diamond
		var leftImage = GenerateLeftSideImage(topImage);
		var rightImage = GenerateRightSideImage(topImage);

		var result = new CachedBlockTextures(
			topTexture,
			ImageTexture.CreateFromImage(leftImage),
			ImageTexture.CreateFromImage(rightImage));

		_textureCache[terrain.StringId] = result;
		return result;
	}

	/// <summary>
	/// Extract the top tile as an Image from an AtlasTexture or regular Texture2D.
	/// </summary>
	private static Image? ExtractImage(Texture2D texture)
	{
		if (texture is AtlasTexture atlas)
		{
			var fullImage = atlas.Atlas?.GetImage();
			if (fullImage == null) return null;
			var region = atlas.Region;
			return fullImage.GetRegion(new Rect2I(
				(int)region.Position.X, (int)region.Position.Y,
				(int)region.Size.X, (int)region.Size.Y));
		}
		return texture.GetImage();
	}

	/// <summary>
	/// Generate left side face (64x32) by sampling the left-bottom edge of the top diamond.
	/// The left-bottom edge runs from Left(-64,0) to Bottom(0,32) in top-image coords
	/// (i.e. pixel coords (0,32) to (64,64) in a 128x64 image).
	/// Each column of the side image samples one point along that edge, then fills
	/// the column with that color darkened by LeftDarken, with a subtle vertical gradient.
	/// </summary>
	private static Image GenerateLeftSideImage(Image topImage)
	{
		const int sw = 64;
		const int sh = 32;
		var img = Image.CreateEmpty(sw, sh, false, Image.Format.Rgba8);
		var tw = topImage.GetWidth();
		var th = topImage.GetHeight();
		var halfW = tw / 2; // 64
		var halfH = th / 2; // 32

		for (var px = 0; px < sw; px++)
		{
			// Map px (0..63) along the left-bottom edge of the diamond:
			// Edge goes from top-image pixel (0, halfH) to (halfW, th-1)
			// i.e. from (0,32) to (64,63)
			var t = px / (float)(sw - 1);
			var sampleX = (int)(t * halfW);
			var sampleY = halfH + (int)(t * (halfH - 1));
			sampleX = Math.Clamp(sampleX, 0, tw - 1);
			sampleY = Math.Clamp(sampleY, 0, th - 1);

			// Sample a small area for smoother color
			var color = SampleArea(topImage, sampleX, sampleY, tw, th);

			for (var py = 0; py < sh; py++)
			{
				// Subtle vertical gradient: top of side slightly brighter
				var gradientFactor = 1.0f - (py / (float)sh) * 0.2f;
				var c = color * new Color(LeftDarken * gradientFactor, LeftDarken * gradientFactor, LeftDarken * gradientFactor, 1f);
				c.A = color.A;
				img.SetPixel(px, py, c);
			}
		}
		return img;
	}

	/// <summary>
	/// Generate right side face (64x32) by sampling the right-bottom edge of the top diamond.
	/// The right-bottom edge runs from Bottom(0,32) to Right(64,0) in top-image coords
	/// (i.e. pixel coords (64,64) to (128,32) in a 128x64 image).
	/// </summary>
	private static Image GenerateRightSideImage(Image topImage)
	{
		const int sw = 64;
		const int sh = 32;
		var img = Image.CreateEmpty(sw, sh, false, Image.Format.Rgba8);
		var tw = topImage.GetWidth();
		var th = topImage.GetHeight();
		var halfW = tw / 2; // 64
		var halfH = th / 2; // 32

		for (var px = 0; px < sw; px++)
		{
			// Map px (0..63) along the right-bottom edge of the diamond:
			// Edge goes from top-image pixel (halfW, th-1) to (tw-1, halfH)
			// i.e. from (64,63) to (127,32)
			var t = px / (float)(sw - 1);
			var sampleX = halfW + (int)(t * (halfW - 1));
			var sampleY = (th - 1) - (int)(t * (halfH - 1));
			sampleX = Math.Clamp(sampleX, 0, tw - 1);
			sampleY = Math.Clamp(sampleY, 0, th - 1);

			var color = SampleArea(topImage, sampleX, sampleY, tw, th);

			for (var py = 0; py < sh; py++)
			{
				var gradientFactor = 1.0f - (py / (float)sh) * 0.2f;
				var c = color * new Color(RightDarken * gradientFactor, RightDarken * gradientFactor, RightDarken * gradientFactor, 1f);
				c.A = color.A;
				img.SetPixel(px, py, c);
			}
		}
		return img;
	}

	/// <summary>Sample a 3x3 area around (cx,cy) and return the average color.</summary>
	private static Color SampleArea(Image img, int cx, int cy, int w, int h)
	{
		float r = 0, g = 0, b = 0, a = 0;
		var count = 0;
		for (var dy = -1; dy <= 1; dy++)
		for (var dx = -1; dx <= 1; dx++)
		{
			var sx = Math.Clamp(cx + dx, 0, w - 1);
			var sy = Math.Clamp(cy + dy, 0, h - 1);
			var c = img.GetPixel(sx, sy);
			if (c.A < 0.01f) continue; // skip transparent pixels
			r += c.R; g += c.G; b += c.B; a += c.A;
			count++;
		}
		if (count == 0) return new Color(0.5f, 0.5f, 0.5f);
		return new Color(r / count, g / count, b / count, a / count);
	}

	/// <summary>Create a solid-color diamond image (fallback when no atlas tile available).</summary>
	private static Image CreateDiamondImage(int w, int h, Color color)
	{
		var image = Image.CreateEmpty(w, h, false, Image.Format.Rgba8);
		var halfW = w / 2;
		var halfH = h / 2;
		for (var py = 0; py < h; py++)
		for (var px = 0; px < w; px++)
		{
			var dx = Math.Abs(px - halfW) / (float)halfW;
			var dy = Math.Abs(py - halfH) / (float)halfH;
			image.SetPixel(px, py, dx + dy <= 1.0f ? color : Colors.Transparent);
		}
		return image;
	}

	// ── Entity Rendering ──

	private static readonly Vector2 DefaultEntitySpriteScale = new(0.25f, 0.25f);
	private static readonly Vector2 EntitySpriteBaseOffset = new(0f, -8f);
	private readonly Dictionary<string, ImageTexture> _entityMarkerCache = new();

	private void CollectEntityCommands(int cx, int cy, int cz, int halfW, int halfH, int zMin, int zMax)
	{
		_entityCommands.Clear();

		foreach (var actor in _state.Actors.Values)
		{
			if (actor.Z < zMin || actor.Z > zMax) continue;
			if (Math.Abs(actor.X - cx) > halfW || Math.Abs(actor.Y - cy) > halfH) continue;
			var tint = GetVisionTint(actor.X, actor.Y, actor.Z);
			if (tint.A <= 0f) continue;
			var label = actor.Id == _state.PlayerId ? "P" : (actor.Faction == Factions.Hostile ? "!" : "?");
			_entityCommands.Add(new EntityDrawCommand(
				IsoCoordUtil.SortKey(actor.X, actor.Y, actor.Z),
				IsoCoordUtil.WorldToScreen(actor.X, actor.Y, actor.Z),
				actor,
				label,
				tint));
		}

		for (var wy = cy - halfH; wy <= cy + halfH; wy++)
		for (var wx = cx - halfW; wx <= cx + halfW; wx++)
		for (var wz = zMax; wz >= zMin; wz--)
		{
			var entities = _state.World!.GetEntities(wx, wy, wz);
			if (entities.Count == 0) continue;
			var tint = GetVisionTint(wx, wy, wz);
			if (tint.A <= 0f) continue;
			var pos = IsoCoordUtil.WorldToScreen(wx, wy, wz);
			var key = IsoCoordUtil.SortKey(wx, wy, wz);
			foreach (var e in entities)
				_entityCommands.Add(new EntityDrawCommand(key, pos, null, e.Glyph, tint));
		}

		_entityCommands.Sort(static (a, b) => a.SortKey.CompareTo(b.SortKey));
	}

	private void RenderScene()
	{
		var terrainIndex = 0;
		var entityIndex = 0;
		while (terrainIndex < _drawCommands.Count || entityIndex < _entityCommands.Count)
		{
			if (entityIndex >= _entityCommands.Count
				|| (terrainIndex < _drawCommands.Count && _drawCommands[terrainIndex].SortKey <= _entityCommands[entityIndex].SortKey))
			{
				var terrain = _drawCommands[terrainIndex++];
				if (terrain.DrawTop) DrawBlockTop(terrain);
				if (terrain.DrawLeftSide) DrawLeftSide(terrain);
				if (terrain.DrawRightSide) DrawRightSide(terrain);
				continue;
			}

			var entity = _entityCommands[entityIndex++];
			if (entity.Actor != null && TryDrawActorSprite(entity.ScreenPos, entity.Actor, entity.Tint))
				continue;
			DrawEntityMarker(entity.ScreenPos, entity.Label, entity.Tint);
		}
	}

	private bool TryDrawActorSprite(Vector2 pos, Actor actor, Color tint)
	{
		if (!TryResolveActorSpriteVisual(actor, out var visual))
			return false;

		var size = visual.Region?.Size ?? visual.Texture.GetSize();
		var sprite = AcquireSprite();
		sprite.Centered = false;
		sprite.Texture = visual.Texture;
		sprite.TextureFilter = CanvasItem.TextureFilterEnum.Nearest;
		sprite.RegionEnabled = visual.Region != null;
		if (visual.Region is { } region)
			sprite.RegionRect = region;
		sprite.Scale = visual.Scale;
		sprite.Skew = 0f;
		sprite.ZIndex = 1;
		sprite.Modulate = tint;
		sprite.Position = pos + EntitySpriteBaseOffset + visual.Offset + new Vector2(
			-(size.X * visual.Scale.X) / 2f,
			-(size.Y * visual.Scale.Y));
		sprite.Visible = true;
		return true;
	}

	private bool TryResolveActorSpriteVisual(Actor actor, out ActorSpriteVisual visual)
	{
		visual = default;
		var entry = ResolveActorRenderEntry(actor);
		if (entry == null)
			return false;

		Texture2D? texture = null;
		Rect2? region = null;
		if (IsTextureEntry(entry) && entry.TexturePath is { Length: > 0 } texturePath)
		{
			texture = ResAccess.Get<Texture2D>(texturePath);
			if (texture != null)
				region = ResolveEntitySpriteRegion(entry, actor, texture);
		}
		else if (IsSpriteSheetEntry(entry))
		{
			var sheetPath = ResolveCharacterSheetPath(entry);
			if (sheetPath.Length > 0)
			{
				texture = ResAccess.Get<Texture2D>(sheetPath);
				if (texture != null)
					region = ResolveCharacterSheetRegion(entry, actor, texture);
			}
		}

		if (texture == null)
			return false;

		visual = new ActorSpriteVisual(
			texture,
			region,
			ResolveEntitySpriteScale(entry.Scale),
			ResolveEntitySpriteOffset(entry.Offset));
		return true;
	}

	private static Vector2 ResolveEntitySpriteScale(float[]? scale)
	{
		if (scale is [var x, var y] && x > 0f && y > 0f)
			return new Vector2(x, y);
		return DefaultEntitySpriteScale;
	}

	private static Vector2 ResolveEntitySpriteOffset(float[]? offset)
	{
		if (offset is [var x, var y])
			return new Vector2(x, y);
		return Vector2.Zero;
	}

	private static Rect2? ResolveEntitySpriteRegion(ResAccess.RenderEntry entry, Actor actor, Texture2D texture)
	{
		if (!entry.UseFacing)
			return null;

		var textureWidth = (int)texture.GetWidth();
		var textureHeight = (int)texture.GetHeight();
		if (textureWidth <= 0 || textureHeight <= 0)
			return null;

		var frameWidth = entry.FrameWidth > 0 ? Math.Min(entry.FrameWidth, textureWidth) : textureWidth;
		var inferredFrameHeight = textureHeight % 8 == 0 ? textureHeight / 8 : textureHeight;
		var frameHeight = entry.FrameHeight > 0 ? Math.Min(entry.FrameHeight, textureHeight) : inferredFrameHeight;
		if (frameWidth <= 0 || frameHeight <= 0)
			return null;

		var rowCount = Math.Max(1, textureHeight / frameHeight);
		var row = Math.Clamp(
			DirectionalSpriteHelper.ResolveDirectionRow(actor.FacingX, actor.FacingY),
			0,
			rowCount - 1);
		return new Rect2(0, row * frameHeight, frameWidth, frameHeight);
	}

	private ResAccess.RenderEntry? ResolveActorRenderEntry(Actor actor)
	{
		if (actor.Id == _state.PlayerId)
		{
			var appearance = PlayerAppearanceCatalog.GetOrDefault(_state.PlayerAppearanceId);
			var tuning = ResAccess.GetEntry("player");
			return new ResAccess.RenderEntry
			{
				Type = "sprite_sheet",
				SheetDir = appearance.SheetDir,
				DefaultAnim = appearance.DefaultAnim,
				Scale = tuning?.Scale,
				Offset = tuning?.Offset,
				FrameWidth = tuning?.FrameWidth ?? 0,
				FrameHeight = tuning?.FrameHeight ?? 0,
				UseFacing = true,
			};
		}

		if (TryGetSupportedActorEntry(actor.Id, out var direct))
			return direct;
		if (!string.IsNullOrWhiteSpace(actor.TemplateId) && TryGetSupportedActorEntry(actor.TemplateId, out var template))
			return template;
		if (actor.Race?.Id is { Length: > 0 } raceId && TryGetSupportedActorEntry(raceId, out var race))
			return race;

		return null;
	}

	private static bool TryGetSupportedActorEntry(string key, out ResAccess.RenderEntry? entry)
	{
		entry = ResAccess.GetEntry(key);
		return IsTextureEntry(entry) || IsSpriteSheetEntry(entry);
	}

	private static bool IsSpriteSheetEntry(ResAccess.RenderEntry? entry) =>
		entry != null
		&& string.Equals(entry.Type, "sprite_sheet", StringComparison.OrdinalIgnoreCase)
		&& !string.IsNullOrWhiteSpace(entry.SheetDir);

	private static string ResolveCharacterSheetPath(ResAccess.RenderEntry entry)
	{
		if (string.IsNullOrWhiteSpace(entry.SheetDir))
			return string.Empty;
		var animationKey = string.IsNullOrWhiteSpace(entry.DefaultAnim) ? "Idle" : entry.DefaultAnim!;
		var sheetKey = CharacterSheetMap.TryGetValue(animationKey, out var resolved) ? resolved : "Idle";
		return $"{entry.SheetDir!.TrimEnd('/')}/{sheetKey}.png";
	}

	private static Rect2? ResolveCharacterSheetRegion(ResAccess.RenderEntry entry, Actor actor, Texture2D texture)
	{
		var textureWidth = (int)texture.GetWidth();
		var textureHeight = (int)texture.GetHeight();
		if (textureWidth <= 0 || textureHeight <= 0)
			return null;

		var frameWidth = entry.FrameWidth > 0
			? Math.Min(entry.FrameWidth, textureWidth)
			: Math.Min(DefaultCharacterSheetFrameWidth, textureWidth);
		var frameHeight = entry.FrameHeight > 0
			? Math.Min(entry.FrameHeight, textureHeight)
			: Math.Min(DefaultCharacterSheetFrameHeight, textureHeight);
		if (frameWidth <= 0 || frameHeight <= 0)
			return null;

		var rowCount = Math.Max(1, textureHeight / frameHeight);
		var row = Math.Clamp(
			DirectionalSpriteHelper.ResolveDirectionRow(actor.FacingX, actor.FacingY),
			0,
			rowCount - 1);
		return new Rect2(0, row * frameHeight, frameWidth, frameHeight);
	}

	private static bool IsTextureEntry(ResAccess.RenderEntry? entry) =>
		entry != null
		&& string.Equals(entry.Type, "texture", StringComparison.OrdinalIgnoreCase)
		&& !string.IsNullOrWhiteSpace(entry.TexturePath);

	private void DrawEntityMarker(Vector2 pos, string label, Color tint)
	{
		var s = AcquireSprite();
		s.Centered = true;
		s.RegionEnabled = false;
		s.Scale = Vector2.One;
		s.Texture = GetEntityMarkerTexture(label);
		s.Position = pos - new Vector2(0, IsoCoordUtil.TileHalfH * 0.5f);
		s.Skew = 0f;
		s.ZIndex = 1;
		s.Modulate = tint;
		s.Visible = true;
	}

	private ImageTexture GetEntityMarkerTexture(string label)
	{
		if (_entityMarkerCache.TryGetValue(label, out var cached)) return cached;
		const int size = 32;
		var image = Image.CreateEmpty(size, size, false, Image.Format.Rgba8);
		var center = size / 2f;
		var radius = size / 2f - 2f;
		var color = label switch
		{
			"P" => new Color(0.2f, 0.6f, 1.0f),
			"!" => new Color(1.0f, 0.2f, 0.2f),
			"?" => new Color(0.2f, 0.8f, 0.2f),
			_ => new Color(0.8f, 0.8f, 0.8f),
		};
		for (var py = 0; py < size; py++)
		for (var px = 0; px < size; px++)
		{
			var dx = px - center;
			var dy = py - center;
			image.SetPixel(px, py, dx * dx + dy * dy <= radius * radius ? color : Colors.Transparent);
		}
		var tex = ImageTexture.CreateFromImage(image);
		_entityMarkerCache[label] = tex;
		return tex;
	}

	// ── Sprite Pool ──

	private void BeginFrame() { _spriteCount = 0; }

	private void EndFrame()
	{
		for (var i = _spriteCount; i < _spritePool.Count; i++)
			_spritePool[i].Visible = false;
	}

	private Sprite2D AcquireSprite()
	{
		var idx = _spriteCount++;
		if (idx < _spritePool.Count) return _spritePool[idx];
		var sprite = new Sprite2D
		{
			Name = "VoxelSprite" + _spritePool.Count.ToString(),
			Centered = true,
			TextureFilter = CanvasItem.TextureFilterEnum.Nearest,
		};
		_root!.AddChild(sprite);
		_spritePool.Add(sprite);
		return sprite;
	}

	private void UpdateCamera(int cx, int cy, int cz)
	{
		if (_camera != null)
			_camera.Position = IsoCoordUtil.WorldToScreen(cx, cy, cz);
	}

	// ── Types ──

	private struct VoxelDrawCommand
	{
		public int WorldX, WorldY, WorldZ;
		public Vector2 ScreenPos;
		public long SortKey;
		public TerrainDef Terrain;
		public bool DrawTop, DrawLeftSide, DrawRightSide;
	}

	private readonly record struct EntityDrawCommand(
		long SortKey,
		Vector2 ScreenPos,
		Actor? Actor,
		string Label,
		Color Tint);

	private readonly record struct ActorSpriteVisual(
		Texture2D Texture,
		Rect2? Region,
		Vector2 Scale,
		Vector2 Offset);

	private record struct CachedBlockTextures(Texture2D? Top, Texture2D? Left, Texture2D? Right);
}
